"""Tables 3, 5, 6, 7 and 8, Supplementary Tables S1-S5, and every other number quoted in Sections 4.2-4.4.

Output: results/tables/*.csv (full precision) and results/RESULTS.md (formatted as in the manuscript).
"""
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'src'))
import numpy as np
import pandas as pd
from sklearn.metrics import roc_curve
from common import *

cv = load_cv()
feed = (cv.activity == 'feeding').values
md = ['# Results reproduced from the saved predictions\n',
      'Generated by `scripts/01_results_tables.py`. Balanced accuracy (BA) in %, 95% CI from 2,000 bootstrap resamples of videos (seed 0).\n']


def md_table(df, title, note=None):
    md.append(f'\n## {title}\n')
    md.append(df.to_markdown(index=False))
    if note:
        md.append(f'\n*{note}*')
    md.append('')


def ba_ci(s):
    return f"{pct(s['balanced_accuracy'])} ({pct(s['ci_low'])}–{pct(s['ci_high'])})"


# ------------------------------------------------------------------ Table 3: dataset and folds
enc = load_sex_variants()
tracks = enc[(enc.backbone == 'dinov2_s') & (enc.crop == 'full') & (enc.train_on == 'feeding_only')].set_index('seq').crab_track
cv['crab_track'] = tracks.loc[cv.seq].values
groups = ['female feeding', 'male feeding', 'male waving']
rows = [dict(row='All data', **{g: int((cv.group == g).sum()) for g in groups}, sequences=len(cv), videos=cv.video.nunique()),
        dict(row='Videos with the class', **{g: cv[cv.group == g].video.nunique() for g in groups}, sequences='', videos=''),
        dict(row='Crab tracks', **{g: cv[cv.group == g].crab_track.nunique() for g in groups}, sequences=cv.crab_track.nunique(), videos='')]
for k in range(5):
    f = cv[cv.fold == k]
    rows.append(dict(row=f'Fold {k + 1}', **{g: int((f.group == g).sum()) for g in groups}, sequences=len(f), videos=f.video.nunique()))
t3 = pd.DataFrame(rows)
t3.to_csv(TABLES / 'Table3_dataset_folds.csv', index=False)
md_table(t3, 'Table 3. Composition of the dataset and of the five video-grouped folds')
assert not set(cv[cv.fold == 0].video) & set(cv[cv.fold != 0].video), 'a video appears in more than one fold'

# ------------------------------------------------------------------ Table 5: activity
rows, show = [], []
for m in ACT_MODELS:
    s = summary(cv.y_act, cv[f'{m}|act'], cv.video)
    fold_ba = [balanced_accuracy(cv.y_act[cv.fold == k], cv[f'{m}|act'][cv.fold == k]) for k in range(5)]
    fpr, tpr, _ = roc_curve(cv.y_act, cv[f'{m}|act'])
    rows.append(dict(model=m, **s, fold_sd=np.std(fold_ba, ddof=1), best_threshold_ba=((tpr - fpr + 1) / 2).max()))
    show.append({'Model': m, 'Balanced accuracy, % (95% CI)': ba_ci(s), 'Waving recall, %': pct(s['recall_positive']),
                 'Feeding recall, %': pct(s['recall_negative']), 'Accuracy, %': pct(s['accuracy']), 'ROC-AUC': f"{s['roc_auc']:.2f}"})
t5 = pd.DataFrame(rows)
t5.to_csv(TABLES / 'Table5_activity_cv.csv', index=False)
md_table(pd.DataFrame(show), 'Table 5. Activity recognition under video-grouped five-fold cross-validation (n = 278; 97 waving)',
         f"Majority-class baseline: {pct(t5.majority_baseline[0])}% accuracy. Fold SD of BA: "
         + ', '.join(f'{m} {sd:.3f}' for m, sd in zip(t5.model, t5.fold_sd))
         + '. Best-threshold BA (Section 4.2): ' + ', '.join(f'{m} {pct(b)}%' for m, b in zip(t5.model, t5.best_threshold_ba)))

# ------------------------------------------------------------------ Table 6: sex
rows, show = [], []
for m in SEX_MODELS:
    a = summary(cv.y_sex, cv[f'{m}|sex'], cv.video)
    f = summary(cv.y_sex[feed], cv[f'{m}|sex'][feed], cv.video[feed])
    fold_ba = [balanced_accuracy(cv.y_sex[cv.fold == k], cv[f'{m}|sex'][cv.fold == k]) for k in range(5)]
    rows.append(dict(model=m, **{f'all_{k}': v for k, v in a.items()}, **{f'feeding_{k}': v for k, v in f.items()},
                     fold_min=min(fold_ba), fold_max=max(fold_ba)))
    show.append({'Model': m, 'All sequences (n = 278): BA, % (95% CI)': ba_ci(a),
                 'Feeding only (n = 181): BA, % (95% CI)': ba_ci(f), 'ROC-AUC (all / feeding)': f"{a['roc_auc']:.2f} / {f['roc_auc']:.2f}"})
t6 = pd.DataFrame(rows)
t6.to_csv(TABLES / 'Table6_sex_cv.csv', index=False)
md_table(pd.DataFrame(show), 'Table 6. Sex identification under video-grouped cross-validation',
         f"Majority-class baseline: {pct(t6.all_majority_baseline[0])}% on all sequences, {pct(t6.feeding_majority_baseline[0])}% on feeding sequences. "
         f"DINOv2 + LR fold BA range: {pct(t6.fold_min[0])}–{pct(t6.fold_max[0])}%.")

# ------------------------------------------------------------------ Table 7: McNemar + Holm
pairs = [('Activity', R3D, TSA, 'act', None), ('Activity', R3D, TS, 'act', None), ('Activity', R3D, EFF, 'act', None),
         ('Activity', EFF, TSA, 'act', None), ('Activity', TSA, TS, 'act', None),
         ('Sex, feeding only', DINO, R3D, 'sex', feed), ('Sex, feeding only', DINO, EFF, 'sex', feed),
         ('Sex, feeding only', DINO, TSA, 'sex', feed), ('Sex, all', DINO, R3D, 'sex', None)]
rows = []
for task, a, b, kind, mask in pairs:
    mask = np.ones(len(cv), bool) if mask is None else mask
    t = cv[f'y_{kind}'].values[mask]
    a_only, b_only, p = mcnemar_exact(t, cv[f'{a}|{kind}'].values[mask], cv[f'{b}|{kind}'].values[mask])
    n_a, n_b = int(((cv[f'{a}|{kind}'].values[mask] > THRESHOLD) == t).sum()), int(((cv[f'{b}|{kind}'].values[mask] > THRESHOLD) == t).sum())
    assert a_only - b_only == n_a - n_b          # consistency with Tables 5 and 6
    rows.append(dict(task=task, family='activity' if kind == 'act' else 'sex', model_a=a, model_b=b, n=int(mask.sum()),
                     a_only=a_only, b_only=b_only, correct_a=n_a, correct_b=n_b, p=p))
t7 = pd.DataFrame(rows)
for fam, idx in t7.groupby('family').groups.items():
    t7.loc[idx, 'p_holm'] = holm(t7.loc[idx, 'p'])
t7.to_csv(TABLES / 'Table7_mcnemar.csv', index=False)
md_table(t7.assign(p=t7.p.map(fmt_p), p_holm=t7.p_holm.map(fmt_p))[['task', 'model_a', 'model_b', 'n', 'a_only', 'b_only', 'p', 'p_holm']]
         .rename(columns={'task': 'Task', 'model_a': 'Model A', 'model_b': 'Model B', 'a_only': 'A only', 'b_only': 'B only', 'p_holm': 'p (Holm)'}),
         'Table 7. Exact McNemar tests between models',
         'Exact two-sided binomial test on discordant sequences; p (Holm): adjusted within each task (5 activity, 4 sex comparisons).')

# ------------------------------------------------------------------ Table S4: errors by class group
rows = []
for m in [R3D, EFF, TS, TSA, DINO]:
    r = {'Model': m}
    if f'{m}|act' in cv:
        wrong = (cv[f'{m}|act'] > THRESHOLD) != (cv.y_act == 1)
        r.update({f'Activity: {g} wrong': int((wrong & (cv.group == g)).sum()) for g in groups})
    wrong = (cv[f'{m}|sex'] > THRESHOLD) != (cv.y_sex == 1)
    r.update({f'Sex: {g} wrong': int((wrong & (cv.group == g)).sum()) for g in groups})
    rows.append(r)
ts4 = pd.DataFrame(rows).astype(object).where(lambda d: d.notna(), '—')
for c in ts4.columns[1:]:
    ts4[c] = ts4[c].map(lambda v: v if v == '—' else int(v))
ts4.to_csv(TABLES / 'TableS4_errors_by_group.csv', index=False)
med = cv.groupby('group')[f'{EFF}|act'].median()
md_table(ts4, 'Table S4. Misclassified sequences by class group (cross-validation, n = 278: 101 FF, 80 MF, 97 MW)',
         f"Median p(waving) of EfficientNet-B0 + BiLSTM: male feeding {med['male feeding']:.2f}, female feeding {med['female feeding']:.2f} (Section 4.2).")

# ------------------------------------------------------------------ Table S5: image-encoder variants (from saved predictions)
rows = []
for (bb, crop, train_on), g in enc.groupby(['backbone', 'crop', 'train_on'], sort=False):
    t, p, f = (g.sex == 'male').astype(int).values, g.p_male_seq.values, (g.activity == 'feeding').values
    rows.append(dict(encoder={'dinov2_s': 'DINOv2 ViT-S/14', 'convnext_t': 'ConvNeXt-T (ImageNet)'}[bb],
                     crop={'full': 'Full', 'tight': 'Central 70%'}[crop], trained_on={'all': 'All', 'feeding_only': 'Feeding only'}[train_on],
                     ba_all=balanced_accuracy(t, p), ba_feeding=balanced_accuracy(t[f], p[f])))
ts5 = pd.DataFrame(rows).sort_values(['encoder', 'crop', 'trained_on'], ascending=[False, False, False])
ts5.to_csv(TABLES / 'TableS5_sex_encoder_variants.csv', index=False)
md_table(ts5.assign(ba_all=ts5.ba_all.map(pct), ba_feeding=ts5.ba_feeding.map(pct))
         .rename(columns={'ba_all': 'All sequences (n = 278)', 'ba_feeding': 'Feeding only (n = 181)'}),
         'Table S5. Sex-classifier variants (balanced accuracy, %)')

# ------------------------------------------------------------------ external tests: Table 8, S1, S2
e71, e90, e64 = load_external('primary71'), load_external('secondary90'), load_external('mismatched64')
ACT_COLS = [(R3D, 'p_waving_r3d18'), (TSA, 'p_waving_aug'), (TS, 'p_waving_noaug')]
ext_rows = []


def ext(label, d, kind, col, table):
    s = summary(d[f'y_{kind}'], d[col], d.video, order='appearance')
    ext_rows.append(dict(table=table, test=label, **s))


f71 = e71.activity == 'feeding'
ext('Sex, DINOv2 + LR (pre-declared, E1)', e71, 'sex', 'p_male', 'Table 8')
ext('Sex, DINOv2 + LR, after blind QC (E1)', e71[~e71.blind_exclude], 'sex', 'p_male', 'Table 8')
ext('Sex, DINOv2 + LR, feeding only (E1)', e71[f71], 'sex', 'p_male', 'Table 8')
for m, c in ACT_COLS:
    ext(f'Activity, {m} (E1 + E2)', e90, 'act', c, 'Table 8')
ext('Sex, DINOv2 + LR', e90, 'sex', 'p_male', 'Table S1')
ext('Sex, DINOv2 + LR, feeding only', e90[e90.activity == 'feeding'], 'sex', 'p_male', 'Table S1')
for m, c in ACT_COLS:
    ext(f'Activity, {m}', e90, 'act', c, 'Table S1')
ext('Activity, R3D-18, without blind-QC exclusions and the 17.7 fps clip', e90[~e90.blind_exclude & ~e90.low_fps], 'act', 'p_waving_r3d18', 'Table S1')
ext('Sex, DINOv2 + LR', e64, 'sex', 'p_male', 'Table S2')
for m, c in ACT_COLS[1:]:
    ext(f'Activity, {m}', e64, 'act', c, 'Table S2')
te = pd.DataFrame(ext_rows)
te.to_csv(TABLES / 'Table8_S1_S2_external.csv', index=False)
for tab in ['Table 8', 'Table S1', 'Table S2']:
    x = te[te.table == tab]
    md_table(pd.DataFrame({'Test': x.test, 'Clips (positive)': [f'{n} ({k})' for n, k in zip(x.n, x.n_positive)],
                           'BA, % (95% CI)': [ba_ci(r) for _, r in x.iterrows()],
                           'Recall positive / negative, %': [f'{pct(a)} / {pct(b)}' for a, b in zip(x.recall_positive, x.recall_negative)],
                           'Majority baseline, %': x.majority_baseline.map(pct), 'ROC-AUC': x.roc_auc.map(lambda v: f'{v:.2f}')}),
             {'Table 8': 'Table 8. External tests with locked models', 'Table S1': 'Table S1. Secondary external analysis (90 clips, E1 + E2)',
              'Table S2': 'Table S2. First external run with mismatched clip extraction (64 clips)'}[tab])

# in-text external numbers (Sections 4.4.1 and 4.4.2)
y = e71.p_male > THRESHOLD
txt = [f"E1 primary: {int((y & (e71.y_sex == 1)).sum())}/{int(e71.y_sex.sum())} males and {int((~y & (e71.y_sex == 0)).sum())}/{int((e71.y_sex == 0).sum())} females correct; {e71.video.nunique()} videos.",
       f"E1 + E2: R3D-18 labelled {int(((e90.p_waving_r3d18 > THRESHOLD) & (e90.sex == 'male') & (e90.activity == 'feeding')).sum())} of {int(((e90.sex == 'male') & (e90.activity == 'feeding')).sum())} male feeding clips "
       f"and {int(((e90.p_waving_r3d18 > THRESHOLD) & (e90.sex == 'female')).sum())} of {int((e90.sex == 'female').sum())} female feeding clips as waving."]
a_only, b_only, p = mcnemar_exact(e90.y_act, e90.p_waving_r3d18, e90.p_waving_aug)
txt.append(f'E1 + E2 activity, R3D-18 vs two-stream (res. aug.): {a_only} vs {b_only} discordant clips, p {fmt_p(p) if fmt_p(p).startswith("<") else "= " + fmt_p(p)}.')
md.append('\n## Other numbers quoted in Section 4.4\n')
md += [f'- {t}' for t in txt]

(RESULTS / 'RESULTS.md').write_text('\n'.join(md) + '\n', encoding='utf-8')
print('\n'.join(md))
print('\nSaved tables in', TABLES, 'and', RESULTS / 'RESULTS.md')
